-- LAUNCH-0 (owner decisions, artifacts/LAUNCH-0/): production cleanup before opening the shop.
-- Data only, no schema change; applied once by the deploy pipeline after the classifier's approval
-- (every statement is an UPDATE or an INSERT...SELECT scoped by id/key/ref). No row is deleted: demo
-- products are archived and inactive categories stay in place, so the client can restore them.
-- A no-op on an empty database: every statement matches rows only when they exist, and migrations run
-- before the seed locally.
--
-- Demo products: only those on sale (status 'active') with placeholder=1 are archived. Products
-- 111-114 (pack components, status 'draft') stay as they are: already off sale, and the admin's pack
-- editor only offers non-archived products, so archiving them would orphan the real packs' contents.
UPDATE `products` SET `status` = 'archived', `updated_at` = cast(unixepoch('subsec') * 1000 as integer) WHERE `placeholder` = 1 AND `status` = 'active';
--> statement-breakpoint
-- Categories: only those holding a real product stay published. An inactive parent hides its whole
-- subtree (publication.ts), so 1 and 11 stay active; 12 (the empty Robinetterie) and every demo branch go.
UPDATE `categories` SET `active` = 0, `updated_at` = cast(unixepoch('subsec') * 1000 as integer) WHERE `id` NOT IN (1, 11) AND `active` = 1;
--> statement-breakpoint
UPDATE `categories` SET `placeholder` = 0, `translation_placeholder` = '[]', `updated_at` = cast(unixepoch('subsec') * 1000 as integer),
  `description_fr` = 'Des packs complets pour équiper votre salle de bain : colonne de douche, mitigeur de lavabo et robinet de toilette.',
  `description_ar` = 'أطقم كاملة لتجهيز حمّامك: عمود استحمام وخلّاط مغسلة وحنفية مرحاض.'
WHERE `id` = 1;
--> statement-breakpoint
UPDATE `categories` SET `placeholder` = 0, `translation_placeholder` = '[]', `updated_at` = cast(unixepoch('subsec') * 1000 as integer),
  `description_fr` = 'Colonne de douche, mitigeur de lavabo et robinet de toilette réunis dans un seul pack, à prix unique.',
