WHERE `id` = 11;
--> statement-breakpoint
-- Delivery fees: all 69 confirmed and deliverable, including wilayas 50 and 54 at their 1,600 DZD.
-- (Migration 0005's trigger guards orders.fee_source only; delivery_fees has no such column.)
UPDATE `delivery_fees` SET `placeholder` = 0, `available` = 1, `updated_at` = cast(unixepoch('subsec') * 1000 as integer) WHERE `placeholder` <> 0 OR `available` <> 1;
--> statement-breakpoint
