-- The two test orders (ref AND test name, still 'new'): cancelled the way the admin cancels, per
-- @hb/db buildOrderChange. The transition table has no new -> cancelled, so the order goes
-- new -> called -> cancelled with one status_change each; stock comes back from order_items.stock_taken
-- only on still-tracked variants, guarded by stock_restored_at; the version bump runs last.
INSERT INTO `order_events` (`order_id`, `type`, `from_status`, `to_status`, `outcome`, `actor_type`, `at`)
SELECT o.`id`, 'status_change', 'new', 'called', NULL, 'system', cast(unixepoch('subsec') * 1000 as integer) FROM `orders` o WHERE o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new' ORDER BY o.`id`;
--> statement-breakpoint
INSERT INTO `order_events` (`order_id`, `type`, `from_status`, `to_status`, `outcome`, `actor_type`, `at`)
SELECT o.`id`, 'status_change', 'called', 'cancelled', 'other', 'system', cast(unixepoch('subsec') * 1000 as integer) FROM `orders` o WHERE o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new' ORDER BY o.`id`;
--> statement-breakpoint
INSERT INTO `order_events` (`order_id`, `type`, `note`, `actor_type`, `at`)
SELECT o.`id`, 'note', 'Commande de test (vérification du site avant ouverture), annulée lors du nettoyage de lancement LAUNCH-0. Ne pas livrer.', 'system', cast(unixepoch('subsec') * 1000 as integer) FROM `orders` o WHERE o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new' ORDER BY o.`id`;
--> statement-breakpoint
UPDATE `variants` SET `stock` = `stock` + (SELECT SUM(oi.`stock_taken`) FROM `order_items` oi JOIN `orders` o ON o.`id` = oi.`order_id` WHERE oi.`variant_id` = `variants`.`id` AND o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new' AND o.`stock_restored_at` IS NULL), `updated_at` = cast(unixepoch('subsec') * 1000 as integer)
WHERE `stock` IS NOT NULL AND `id` IN (SELECT oi.`variant_id` FROM `order_items` oi JOIN `orders` o ON o.`id` = oi.`order_id` WHERE o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new' AND o.`stock_restored_at` IS NULL AND oi.`stock_taken` > 0);
--> statement-breakpoint
UPDATE `customers` SET `cancelled_count` = `cancelled_count` + (SELECT count(*) FROM `orders` o WHERE o.`customer_id` = `customers`.`id` AND o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new'), `updated_at` = cast(unixepoch('subsec') * 1000 as integer)
WHERE `id` IN (SELECT o.`customer_id` FROM `orders` o WHERE o.`ref` IN ('HB-EMSH9', 'HB-0X164') AND o.`name` GLOB 'TEST NE PAS LIVRER *' AND o.`status` = 'new');
--> statement-breakpoint
UPDATE `orders` SET `status` = 'cancelled', `version` = `version` + 1, `updated_at` = cast(unixepoch('subsec') * 1000 as integer), `stock_restored_at` = COALESCE(`stock_restored_at`, cast(unixepoch('subsec') * 1000 as integer)), `claimed_by_user_id` = NULL, `claimed_until` = NULL, `next_call_at` = NULL
WHERE `ref` IN ('HB-EMSH9', 'HB-0X164') AND `name` GLOB 'TEST NE PAS LIVRER *' AND `status` = 'new';
